500	TArray<FName> AGBHUD::GetWeaponList(AGBPlayerCharacter* Player) const
501	{
502		TArray<FName> Result;
503		const UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
504		if (!Equipment)
505		{
506			return Result;
507		}
508		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
509		static const EGBHeldSlot Order[] = { EGBHeldSlot::Staff, EGBHeldSlot::Gun, EGBHeldSlot::Sword };
510		for (const EGBHeldSlot Slot : Order)
511		{
512			for (const FName& WeaponId : Equipment->GetOwnedWeapons())
513			{
514				const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(WeaponId) : nullptr;
515				if (Def && Def->Slot == Slot)
516				{
517					Result.AddUnique(WeaponId);
518				}
519			}
520		}
521		// Weapons no longer in the data (after a reload) are still listed, at the end.
522		for (const FName& WeaponId : Equipment->GetOwnedWeapons())
523		{
524			if (WeaponId != NAME_None)
525			{
526				Result.AddUnique(WeaponId);
527			}
528		}
529		return Result;
530	}
