62	EGBSkillUnlockResult UGBSkillTreeComponent::CanUnlock(FName NodeId) const
63	{
64		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
65		const FGBSkillNodeDefinition* Node = Data ? Data->FindSkillNode(NodeId) : nullptr;
66		if (!Node)
67		{
