73	EGBSkillUnlockResult UGBSkillTreeComponent::Unlock(FName NodeId)
74	{
75		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
76		const FGBSkillNodeDefinition* Node = Data ? Data->FindSkillNode(NodeId) : nullptr;
77		if (!Node)
78		{
79			UE_LOG(LogGB, Warning, TEXT("Unlock: unknown skill node '%s'."), *NodeId.ToString());
80			return EGBSkillUnlockResult::UnknownNode;
81		}
82	
83		const EGBSkillUnlockResult Result = EvaluateUnlock(*Node, Ranks, Points);
84		if (Result != EGBSkillUnlockResult::Ok)
85		{
86			return Result;
87		}
88	
89		Points -= FMath::Max(0, Node->Cost);
90		Ranks.FindOrAdd(NodeId) += 1;
91		ApplyNodeModifiers(NodeId);
92		OnSkillsChanged.Broadcast();
93		return EGBSkillUnlockResult::Ok;
94	}
