96	EGBSkillUnlockResult UGBSkillTreeComponent::EvaluateUnlock(const FGBSkillNodeDefinition& Node, const TMap<FName, int32>& InRanks, int32 AvailablePoints)
97	{
98		if (InRanks.FindRef(Node.Id) >= Node.MaxRank)
99		{
100			return EGBSkillUnlockResult::MaxRank;
101		}
102		for (const FName& Required : Node.Requires)
103		{
104			if (!Required.IsNone() && InRanks.FindRef(Required) <= 0)
105			{
106				return EGBSkillUnlockResult::MissingRequirement;
107			}
108		}
109		if (AvailablePoints < Node.Cost)
110		{
111			return EGBSkillUnlockResult::NotEnoughPoints;
112		}
113		return EGBSkillUnlockResult::Ok;
114	}
