121	void UGBSkillTreeComponent::ApplyNodeModifiers(FName NodeId)
122	{
123		UGBStatsComponent* Stats = UGBStatsComponent::Find(GetOwner());
124		if (!Stats)
125		{
126			return;
127		}
128	
129		const FName Source = ModifierSource(NodeId);
130		const int32 Rank = GetRank(NodeId);
131		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
132		const FGBSkillNodeDefinition* Node = Data ? Data->FindSkillNode(NodeId) : nullptr;
133		if (!Node || Rank <= 0)
134		{
135			if (!Node && Rank > 0)
136			{
137				UE_LOG(LogGB, Warning, TEXT("Skill node '%s' is owned but missing from Skills.json; its modifiers are off."), *NodeId.ToString());
138			}
139			Stats->RemoveModifiers(Source);
140			return;
141		}
142	
143		// ValueScale = rank: Add modifiers count once per rank, Multiply modifiers stack linearly (not compounding).
144		Stats->AddModifiers(Source, Node->ModifiersPerRank, static_cast<float>(Rank));
145	}
