185	void AGBHUD::AddMenuHit(EMenuHitKind Kind, float X, float Y, float W, float H, int32 Index, FName Id)
186	{
187		FMenuHit Hit;
188		Hit.Kind = Kind;
189		Hit.Min = FVector2D(X, Y);
190		Hit.Max = FVector2D(X + FMath::Max(0.f, W), Y + FMath::Max(0.f, H));
191		Hit.Index = Index;
192		Hit.Id = Id;
193		MenuHits.Add(Hit);
194	}
195	
196	const AGBHUD::FMenuHit* AGBHUD::FindMenuHit(const FVector2D& CanvasPosition) const
197	{
198		// Last drawn is on top.
199		for (int32 i = MenuHits.Num() - 1; i >= 0; --i)
200		{
201			const FMenuHit& Hit = MenuHits[i];
202			if (CanvasPosition.X >= Hit.Min.X && CanvasPosition.X <= Hit.Max.X && CanvasPosition.Y >= Hit.Min.Y && CanvasPosition.Y <= Hit.Max.Y)
203			{
204				return &Hit;
205			}
206		}
207		return nullptr;
208	}
209	
210	void AGBHUD::UpdateMenuMouse()
211	{
212		APlayerController* PC = GetOwningPlayerController();
213		float MouseX = 0.f;
214		float MouseY = 0.f;
215		if (!PC || !PC->GetMousePosition(MouseX, MouseY))
216		{
217			return;
218		}
219		const FVector2D Mouse(MouseX * MouseToCanvas, MouseY * MouseToCanvas);
220		const bool bMoved = bHasMenuMouse && !Mouse.Equals(LastMenuMouse, 0.5f);
221		LastMenuMouse = Mouse;
222		bHasMenuMouse = true;
223		// Hover uses last frame's clickables, so the highlight moves in the same frame it is drawn.
224		if (bMoved && MenuHitsMenu == GetOpenMenu())
225		{
226			if (const FMenuHit* Hit = FindMenuHit(Mouse))
227			{
228				ApplyMenuHover(*Hit);
229			}
230		}
231	}
232	
233	void AGBHUD::ApplyMenuHover(const FMenuHit& Hit)
234	{
235		switch (Hit.Kind)
236		{
237		case EMenuHitKind::PauseEntry:
238		case EMenuHitKind::ItemRow:
239		case EMenuHitKind::WeaponRow:
240			MenuState.Cursor = Hit.Index;
241			break;
242		case EMenuHitKind::SpellSlot:
243			if (!MenuState.bChoosingSpell)
244			{
245				MenuState.Cursor = Hit.Index;
246			}
247			break;
248		case EMenuHitKind::SpellChoice:
249			MenuState.SubCursor = Hit.Index;
250			break;
251		case EMenuHitKind::SkillNode:
252			MenuState.SkillCursor = Hit.Id;
253			break;
254		default:
255			// Tabs and the death screen only react to clicks.
256			break;
257		}
258	}
259	
260	void AGBHUD::ActivateMenuHit(const FMenuHit& Hit)
261	{
262		AGBPlayerCharacter* Player = GetPlayer();
263		switch (Hit.Kind)
264		{
265		case EMenuHitKind::PauseEntry:
266			MenuState.Cursor = Hit.Index;
267			MenuConfirm();
268			break;
269		case EMenuHitKind::Tab:
270			if (Hit.Index != MenuState.Page)
271			{
272				SetInventoryPage(Hit.Index);
273			}
274			break;
275		case EMenuHitKind::ItemRow:
276			MenuState.Cursor = Hit.Index;
277			ConfirmItem(Player);
278			break;
279		case EMenuHitKind::WeaponRow:
280			MenuState.Cursor = Hit.Index;
281			ConfirmWeapon(Player);
282			break;
283		case EMenuHitKind::SpellSlot:
284			// A click on another slot while choosing leaves the chooser and opens it for that slot.
285			MenuState.bChoosingSpell = false;
286			MenuState.Cursor = Hit.Index;
287			ConfirmSpellSlot(Player);
288			break;
289		case EMenuHitKind::SpellChoice:
290			MenuState.SubCursor = Hit.Index;
291			ConfirmSpellSlot(Player);
292			break;
293		case EMenuHitKind::SkillNode:
294			MenuState.SkillCursor = Hit.Id;
295			ConfirmSkill(Player);
296			break;
297		case EMenuHitKind::DeathScreen:
298			// The controller handles the respawn confirm (AGBPlayerController::InputMenuClick): nothing here,
299			// so a click respawns exactly once.
300			break;
301		}
302	}
303	
304	bool AGBHUD::MenuClick(const FVector2D& ScreenPosition)
305	{
306		const EGBMenu Menu = GetOpenMenu();
307		// Only the clickables of the screen that is showing right now (not of a page left this frame).
308		if (Menu == EGBMenu::None || Menu != MenuHitsMenu || MenuHitsPage != MenuState.Page || bMenuHitsChoosing != MenuState.bChoosingSpell)
309		{
310			return false;
311		}
312		const FVector2D Position = ScreenPosition * MouseToCanvas;
313		const FMenuHit* Found = FindMenuHit(Position);
314		if (!Found)
315		{
316			return false;
317		}
318		// Copy: the action may change the menu, and the list is rebuilt on the next draw.
319		const FMenuHit Hit = *Found;
320		ActivateMenuHit(Hit);
321		return true;
322	}
323	
324	void AGBHUD::MenuNavigate(FIntPoint Direction)
325	{
326		using namespace GBHudMenuLocal;
327		AGBPlayerCharacter* Player = GetPlayer();
328		switch (GetOpenMenu())
329		{
330		case EGBMenu::Pause:
331			if (Direction.Y != 0)
332			{
333				MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, 2);
334			}
335			break;
336		case EGBMenu::SkillTrees:
337			NavigateSkills(Direction);
338			break;
339		case EGBMenu::Inventory:
340			if (MenuState.Page == PageSkills)
341			{
342				NavigateSkills(Direction);
343			}
344			else if (MenuState.Page == PageSpells)
345			{
346				if (Direction.Y == 0)
347				{
348					break;
349				}
350				if (MenuState.bChoosingSpell)
351				{
352					MenuState.SubCursor = Wrap(MenuState.SubCursor + Direction.Y, GetAssignableSpells(Player).Num());
353				}
354				else
355				{
356					MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, UGBSpellbookComponent::NumSlots + 1);
357				}
358			}
359			else if (MenuState.Page == PageWeapons)
360			{
361				if (Direction.Y != 0)
362				{
363					MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, GetWeaponList(Player).Num());
364				}
365			}
366			else if (Direction.Y != 0)
367			{
368				MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, GetInventoryList(Player).Num());
369			}
370			break;
371		default:
372			break;
373		}
374	}
375	
376	void AGBHUD::MenuConfirm()
377	{
378		AGBPlayerCharacter* Player = GetPlayer();
379		switch (GetOpenMenu())
380		{
381		case EGBMenu::Pause:
382			if (MenuState.Cursor == 0)
383			{
384				if (AGBPlayerController* PC = GetGBController())
385				{
386					PC->SetMenu(EGBMenu::None);
387				}
388			}
389			else
390			{
391				UKismetSystemLibrary::QuitGame(this, GetOwningPlayerController(), EQuitPreference::Quit, false);
392			}
393			break;
394		case EGBMenu::SkillTrees:
395			ConfirmSkill(Player);
396			break;
397		case EGBMenu::Inventory:
398			if (MenuState.Page == PageItems)
399			{
400				ConfirmItem(Player);
401			}
402			else if (MenuState.Page == PageWeapons)
403			{
404				ConfirmWeapon(Player);
405			}
406			else if (MenuState.Page == PageSpells)
407			{
408				ConfirmSpellSlot(Player);
409			}
410			else
411			{
412				ConfirmSkill(Player);
413			}
414			break;
415		default:
416			// Death: the controller handles the respawn confirm.
417			break;
418		}
419	}
420	
421	bool AGBHUD::MenuBack()
422	{
423		switch (GetOpenMenu())
424		{
425		case EGBMenu::Inventory:
426			if (MenuState.Page == PageItems && MenuState.PendingCombine != NAME_None)
427			{
428				MenuState.PendingCombine = NAME_None;
429				return true;
430			}
431			if (MenuState.Page == PageSpells && MenuState.bChoosingSpell)
432			{
433				MenuState.bChoosingSpell = false;
434				return true;
435			}
436			return false;
437		case EGBMenu::Death:
438			// The death screen only closes by respawning.
439			return true;
440		default:
441			return false;
442		}
443	}
444	
445	void AGBHUD::MenuTab(int32 Direction)
446	{
447		if (Direction == 0)
448		{
449			return;
450		}
451		const EGBMenu Menu = GetOpenMenu();
452		if (Menu == EGBMenu::Inventory)
453		{
454			SetInventoryPage(MenuState.Page + Direction);
455		}
456		else if (Menu == EGBMenu::SkillTrees)
457		{
458			// Jump to the first node of the other tree.
459			const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
460			const FSkillNodeRef* Current = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
461			const int32 OtherTree = Current ? 1 - Current->Tree : 0;
462			if (const FSkillNodeRef* Other = Nodes.FindByPredicate([OtherTree](const FSkillNodeRef& Node) { return Node.Tree == OtherTree; }))
463			{
464				MenuState.SkillCursor = Other->Id;
465			}
466		}
467	}
