+	PointsSpent = 0;
+	Ranks.Reset();
+	OnSkillsChanged.Broadcast();
+	return Refunded;
+}
+
@@ -168,6 +185,7 @@ void UGBSkillTreeComponent::ReapplyAllModifiers()
