const fs = require('fs');
const p = 'C:/GameJam/Design/GDD.md';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
if (crlf) s = s.split('\r\n').join('\n');
function rep(a, b) { if (!s.includes(a)) throw new Error('missing: ' + a); s = s.split(a).join(b); }
rep('> Status: **v0.17, 2026-11-12**', '> Status: **v0.18, 2026-11-12**');
rep('## Changelog\n', '## Changelog\n- v0.18 (2026-11-12): owner asked for a "+1 skill point" button on the skill tree screen, to test perks.\n');
rep('Whether the final game keeps it free, limits it (for example only at portals) or keeps it only as a test option is open.\n',
    'Whether the final game keeps it free, limits it (for example only at portals) or keeps it only as a test option is open.\n- **"+1 skill point" button (owner asked for it, to test perks):** on the same screen, left of the skill points; each click adds one free point to the pool (no key, no limit). A reset refunds only what was paid, so free points stay. It is a test option: it must be removed or hidden before the jam submission (provisional, architect).\n');
if (crlf) s = s.split('\n').join('\r\n');
fs.writeFileSync(p, s);
console.log('ok');

