const fs = require('fs');
const p = 'C:/GameJam/Design/GDD.md';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
if (crlf) s = s.split('\r\n').join('\n');
function rep(a, b) { if (!s.includes(a)) throw new Error('missing: ' + a); s = s.split(a).join(b); }
rep('> Status: **v0.18, 2026-11-12**', '> Status: **v0.19, 2026-11-12**');
rep('## Changelog\n', '## Changelog\n- v0.19 (2026-11-12): owner: when ground spells overlap, the one placed last covers the others completely, and they never flicker.\n');
rep('The rune shows dimmer until it is armed. The old colored disc is gone.\n',
    'The rune shows dimmer until it is armed. The old colored disc is gone.\n- **Overlapping ground spells (owner, 2026-11-12):** the figure placed last is drawn on top of every figure it overlaps, completely (an ice floor cast over a rune hides the rune where they overlap; a rune cast over an ice floor shows over it), and overlapping figures never flicker. Provisional (architect): each new figure sits a little higher than the highest figure it overlaps (1.5 cm per layer, values in `Game.json`); this is only how it looks, the spells\' areas and effects do not change.\n');
if (crlf) s = s.split('\n').join('\r\n');
fs.writeFileSync(p, s);
console.log('ok');

