const fs = require('fs');
const p = 'C:/GameJam/Design/GDD.md';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
if (crlf) s = s.split('\r\n').join('\n');
function rep(a, b) { if (!s.includes(a)) throw new Error('missing: ' + a); s = s.split(a).join(b); }
rep('> Status: **v0.20, 2026-11-12**', '> Status: **v0.21, 2026-11-12**');
rep('## Changelog\n', '## Changelog\n- v0.21 (2026-11-12): owner: a strong hit (30% of health or more) interrupts the flamethrower, with a camera shake; the spell description says "a strong hit" without the number.\n');
rep('runs while the spell key is held**, until it is released or the mana runs out) |',
    'runs while the spell key is held**, until it is released or the mana runs out; **a strong hit interrupts it**) |');
rep('All values in `Spells.json` (`ManaCost`, `ManaPerSecond`, `MinDuration`).\n',
    'All values in `Spells.json` (`ManaCost`, `ManaPerSecond`, `MinDuration`).\n- **Strong hit interrupts the flamethrower (owner, 2026-11-12):** a single hit that takes **30% or more of the player\'s maximum health** stops it at once, and the camera shakes. The in-game description says "a strong hit", never the number. Provisional (architect): measured against maximum health (not current health), on the damage actually taken after the ice shield and armor; the threshold is a spell parameter (`InterruptHitFraction`, so any sustained spell can use it); the shake is short (about 0.35 s, a few degrees, values in `Game.json`), only moves the view, never the aim; the mana already spent is not refunded and the cooldown is unchanged.\n');
if (crlf) s = s.split('\n').join('\r\n');
fs.writeFileSync(p, s);
console.log('ok');

